do $$
declare e uuid:=gen_random_uuid();w uuid:=gen_random_uuid();x uuid:=gen_random_uuid();ad uuid:=gen_random_uuid();svc uuid;req uuid;o uuid;o2 uuid;wa uuid;j uuid;c uuid;n integer;
begin
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 insert into auth.users(id,email,raw_user_meta_data) values(e,e||'@offers.invalid','{"account_type":"employer"}'),(w,w||'@offers.invalid','{}'),(x,x||'@offers.invalid','{}'),(ad,ad||'@offers.invalid','{}');
 update public.profiles set employer_premium_until=now()+interval '1 day' where id=e;update public.profiles set role='admin' where id=ad;
 perform set_config('request.jwt.claims',json_build_object('sub',w,'role','authenticated')::text,true);set local role authenticated;
 svc:=public.save_worker_service(null,'Test worker','Test editing service','I edit video content for your project with care.','Development','Remote',500,'project','');
 perform public.save_worker_availability(null,now()+interval '2 days',now()+interval '2 days 4 hours');
 perform set_config('request.jwt.claims',json_build_object('sub',x,'role','authenticated')::text,true);
 if exists(select 1 from public.worker_availability where worker_id=w) then raise exception 'Availability leaked to another worker';end if;
 perform set_config('request.jwt.claims',json_build_object('sub',ad,'role','authenticated')::text,true);perform public.review_worker_service(svc,'published','Test');
 perform set_config('request.jwt.claims',json_build_object('sub',e,'role','authenticated')::text,true);
 if not exists(select 1 from public.worker_availability where worker_id=w) then raise exception 'Hirer cannot see availability';end if;
 req:=public.request_worker_service(svc,'Please help edit a short video for my project.',1000);
 o:=public.propose_service_work(req,null,'Edit a short video','Edit a short video with captions and clean audio.',1000,'project','bank','After the accepted delivery','About four hours',null,null);
 o2:=public.propose_service_work(req,o,'Edit a short video','Edit a short video with captions and clean audio.',1200,'day','bank','After the accepted delivery','About one day',null,null);
 perform set_config('request.jwt.claims',json_build_object('sub',x,'role','authenticated')::text,true);
 if exists(select 1 from public.service_work_offers where request_id=req) then raise exception 'Offer privacy failed';end if;
 begin perform public.respond_service_work(o2,'accept');raise exception 'Outsider accepted';exception when raise_exception then if sqlerrm<>'Only the named worker can respond' then raise;end if;end;
 perform set_config('request.jwt.claims',json_build_object('sub',w,'role','authenticated')::text,true);
 begin perform public.respond_service_work(o,'accept');raise exception 'Old offer accepted';exception when raise_exception then if sqlerrm<>'Offer no longer available' then raise;end if;end;
 wa:=public.respond_service_work(o2,'accept');if wa is distinct from public.respond_service_work(o2,'accept') then raise exception 'Duplicate work';end if;
 select job_id into j from public.job_assignments where id=wa;
 if (select state from public.job_assignments where id=wa)<>'assigned' then raise exception 'Work started automatically';end if;
 reset role;perform set_config('request.jwt.claims','{}',true);set local role anon;
 if exists(select 1 from public.jobs where id=j) then raise exception 'Private work is public';end if;
 reset role;perform set_config('request.jwt.claims',json_build_object('sub',w,'role','authenticated')::text,true);set local role authenticated;
 perform public.request_work_change(wa,'reschedule','I need a later start',now()+interval '3 days',null);
 select id into c from public.work_change_requests where assignment_id=wa and status='pending';
 begin perform public.review_work_change(c,'approve');raise exception 'Self approved';exception when raise_exception then if sqlerrm<>'Other participant or admin must decide' then raise;end if;end;
 perform set_config('request.jwt.claims',json_build_object('sub',e,'role','authenticated')::text,true);perform public.review_work_change(c,'approve','Agreed');
 perform set_config('request.jwt.claims',json_build_object('sub',w,'role','authenticated')::text,true);
 begin perform public.update_job_work(wa,'start');raise exception 'Started with stale agreement';exception when raise_exception then if sqlerrm<>'Accept the current work agreement before starting' then raise;end if;end;
 perform set_config('request.jwt.claims',json_build_object('sub',e,'role','authenticated')::text,true);
 select id into o from public.work_agreements where assignment_id=wa order by revision desc limit 1;
 o:=public.propose_work_agreement(wa,o,'Edit a short video with captions and clean audio.',1200,'day','bank','After accepted delivery','One day');
 perform set_config('request.jwt.claims',json_build_object('sub',w,'role','authenticated')::text,true);perform public.respond_work_agreement(o,true);perform public.update_job_work(wa,'start');
 perform public.submit_work_delivery(wa,'The first edit is ready.','{}');
 perform set_config('request.jwt.claims',json_build_object('sub',x,'role','authenticated')::text,true);
 if exists(select 1 from public.work_deliveries where assignment_id=wa) then raise exception 'Delivery leaked';end if;
 perform set_config('request.jwt.claims',json_build_object('sub',e,'role','authenticated')::text,true);perform public.update_job_work(wa,'revise',90,'Please adjust the opening');
 perform set_config('request.jwt.claims',json_build_object('sub',w,'role','authenticated')::text,true);perform public.submit_work_delivery(wa,'The revised edit is ready.',array['https://drive.google.com/file/d/example/view']);
 perform set_config('request.jwt.claims',json_build_object('sub',e,'role','authenticated')::text,true);perform public.update_job_work(wa,'complete',100,'Accepted');
 if (select count(*) from public.work_deliveries where assignment_id=wa)<>2 or not exists(select 1 from public.work_deliveries where assignment_id=wa and revision=2 and status='accepted') then raise exception 'Delivery history missing';end if;

 perform set_config('request.jwt.claims',json_build_object('sub',w,'role','authenticated')::text,true);perform public.respond_service_request(req,'close');
 perform set_config('request.jwt.claims',json_build_object('sub',e,'role','authenticated')::text,true);
 req:=public.request_worker_service(svc,'Another small video editing task for the test.',500);
 o:=public.propose_service_work(req,null,'Edit another video','Edit a second short video with captions and sound.',500,'project','cash','After completion','Flexible time',null,null);
 perform set_config('request.jwt.claims',json_build_object('sub',w,'role','authenticated')::text,true);wa:=public.respond_service_work(o,'accept');
 perform public.request_work_change(wa,'cancel','I am no longer available');
 select id into c from public.work_change_requests where assignment_id=wa and status='pending';
 if (select state from public.job_assignments where id=wa)<>'assigned' then raise exception 'Cancelled without approval';end if;
 perform set_config('request.jwt.claims',json_build_object('sub',e,'role','authenticated')::text,true);perform public.review_work_change(c,'approve','Agreed to cancel');
 if (select state from public.job_assignments where id=wa)<>'cancelled' then raise exception 'Approved cancellation failed';end if;
 select job_id into j from public.job_assignments where id=wa;
 begin perform public.request_reopen_positions(j);raise exception 'Private service republished';exception when raise_exception then if sqlerrm<>'No reopenable positions' then raise;end if;end;
 reset role;
end$$;
rollback;
select 'PASS: private offers, stale/outsider rejection, idempotent acceptance, private jobs, per-worker agreement, availability visibility, mutual rescheduling, optional delivery links, review history; rolled back' as result;
